    const viewCap = type === "activity" ? "activity.view" : type === "poll" ? "poll.view" : ["faq", "knowledge"].includes(type) ? "knowledge.view" : type === "quality_feedback" ? opsRoleRank(authed.role) >= opsRoleRank("admin") ? "quality.manage" : "quality.report" : type === "suggestion" ? opsRoleRank(authed.role) >= opsRoleRank("admin") ? "suggestion.manage" : "suggestion.create" : type === "bug" ? opsRoleRank(authed.role) >= opsRoleRank("admin") ? "bug.manage" : "bug.create" : def.capability;
    const gate = await opsRequire(env, authed, viewCap);
    if (!gate.ok) return gate.response;
    let records = await opsListRecords(env, type, { groupId, qq: authed.qq, role: authed.role, limit: Number(url.searchParams.get("limit") || 300) });
