function opsGetWorkspace(prefix){return opsWorkspaces[prefix]||null}
function opsTypeOptionsFor(types){var defs=(opsBootstrap&&opsBootstrap.recordTypes)||{};return (types||[]).filter(function(k){return defs[k]}).map(function(k){return '<option value="'+esc(k)+'">'+esc(defs[k].name)+'\uFF08'+esc(k)+'\uFF09</option>'}).join('')}
