function safeAttachmentUrl(value){try{var u=new URL(String(value||''),location.href);return /^https?:$/.test(u.protocol)?u.href:''}catch(e){return''}}
function attachmentTypeText(type){return({image:'\u56FE\u7247',record:'\u8BED\u97F3',audio:'\u8BED\u97F3',video:'\u89C6\u9891',file:'\u6587\u4EF6'})[String(type||'').toLowerCase()]||'\u9644\u4EF6'}
function conversationAttachmentProxy(x,source,index,download){var p=new URLSearchParams({id:String(x.messageId||''),source:source,index:String(index)});if(download)p.set('download','1');return'/api/portal/conversations/attachment?'+p.toString()}
function conversationAttachmentHtml(x){var rows=[];(x.media||[]).forEach(function(m,index){var type=String(m.type||'').toLowerCase(),label='['+attachmentTypeText(type)+']',name=String(m.name||m.file||''),preview=conversationAttachmentProxy(x,'media',index,false),download=conversationAttachmentProxy(x,'media',index,true);rows.push('<button type="button" class="attachment-link" data-attachment-preview="'+esc(preview)+'" data-attachment-type="'+esc(type)+'" data-attachment-name="'+esc(name||label)+'">'+esc(label)+'</button><a class="attachment-link" href="'+esc(preview)+'" target="_blank" rel="noopener noreferrer">\u65B0\u5206\u9875\u6253\u5F00</a><a class="attachment-link" href="'+esc(download)+'">\u4E0B\u8F7D</a>')});(x.files||[]).forEach(function(f,index){var name=String(f.name||f.file||'\u672A\u547D\u540D\u6587\u4EF6'),label='[\u6587\u4EF6] '+name,open=conversationAttachmentProxy(x,'files',index,false),download=conversationAttachmentProxy(x,'files',index,true);rows.push('<a class="attachment-link" href="'+esc(open)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a><a class="attachment-link" href="'+esc(download)+'">\u4E0B\u8F7D</a>')});return rows.length?'<div class="conversation-attachments">'+rows.join('')+'</div>':''}
function ensureAttachmentPreview(){if($('attachmentPreview'))return;var d=document.createElement('div');d.id='attachmentPreview';d.className='qqai-modal hidden';d.innerHTML='<div class="qqai-modal-card attachment-modal-card"><h3 id="attachmentPreviewTitle">\u67E5\u770B\u9644\u4EF6</h3><div id="attachmentPreviewBody" class="attachment-preview-body"></div><div class="qqai-modal-actions"><a id="attachmentPreviewOpen" class="btn" target="_blank" rel="noopener noreferrer">\u5728\u65B0\u5206\u9875\u6253\u5F00</a><a id="attachmentPreviewDownload" class="btn">\u4E0B\u8F7D</a><button id="attachmentPreviewClose" class="btn primary">\u5173\u95ED</button></div></div>';document.body.appendChild(d);$('attachmentPreviewClose').onclick=function(){closeAttachmentPreview()};d.onclick=function(e){if(e.target===d)closeAttachmentPreview()}}
function closeAttachmentPreview(){if(!$('attachmentPreview'))return;$('attachmentPreview').classList.add('hidden');$('attachmentPreviewBody').innerHTML=''}
function attachmentDownloadVariant(url){try{var u=new URL(url,location.href);u.searchParams.set('download','1');return u.href}catch(e){return url}}
function attachmentPreviewFailure(url,type,name){var body=$('attachmentPreviewBody');body.innerHTML='<div class="attachment-error"><b>\u9644\u4EF6\u52A0\u8F7D\u5931\u8D25</b><p>QQ \u56FE\u7247\u76F4\u94FE\u53EF\u80FD\u5DF2\u8FC7\u671F\uFF0C\u7CFB\u7EDF\u5DF2\u7ECF\u5C1D\u8BD5\u901A\u8FC7 NapCat \u5237\u65B0\u3002\u8BF7\u786E\u8BA4 NapCat \u5728\u7EBF\u540E\u91CD\u8BD5\u3002</p><button id="attachmentRetry" class="btn primary">\u91CD\u8BD5</button></div>';$('attachmentRetry').onclick=function(){openAttachmentPreview(url,type,name)}}
function openAttachmentPreview(url,type,name){ensureAttachmentPreview();url=safeAttachmentUrl(url);if(!url){toast('\u9644\u4EF6\u94FE\u63A5\u65E0\u6548');return}$('attachmentPreviewTitle').textContent=name||attachmentTypeText(type);$('attachmentPreviewOpen').href=url;$('attachmentPreviewDownload').href=attachmentDownloadVariant(url);var body=$('attachmentPreviewBody'),t=String(type||'').toLowerCase();body.innerHTML='<div class="muted">\u6B63\u5728\u52A0\u8F7D\u9644\u4EF6\u2026</div>';if(t==='image'){var img=document.createElement('img');img.alt='\u9644\u4EF6\u56FE\u7247';img.onload=function(){body.innerHTML='';body.appendChild(img)};img.onerror=function(){attachmentPreviewFailure(url,type,name)};img.src=url}else if(t==='video'){var video=document.createElement('video');video.controls=true;video.playsInline=true;video.onloadeddata=function(){body.innerHTML='';body.appendChild(video)};video.onerror=function(){attachmentPreviewFailure(url,type,name)};video.src=url;video.load()}else if(t==='record'||t==='audio'){var audio=document.createElement('audio');audio.controls=true;audio.onloadeddata=function(){body.innerHTML='';body.appendChild(audio)};audio.onerror=function(){attachmentPreviewFailure(url,type,name)};audio.src=url;audio.load()}else body.innerHTML='<a class="attachment-link" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">\u6253\u5F00\u9644\u4EF6</a>';$('attachmentPreview').classList.remove('hidden')}
function renderConversationRecord(x){var summary=[];if((x.forwardIds||[]).length)summary.push('\u5408\u5E76\u8F6C\u53D1 '+x.forwardIds.length+' \u4E2A');var badge=x.violationActive?'<span class="violation-badge">\u8FDD\u89C4\u4FE1\u606F</span>':'';var status=[];if(x.essence)status.push('\u7CBE\u534E');if(x.groupTodo)status.push('\u7FA4\u5F85\u529E');if(x.recalledAt)status.push('\u5DF2\u64A4\u56DE');var detail={\u6587\u4EF6:x.files||[],\u5A92\u4F53:x.media||[],\u8F6C\u53D1:x.forwardSnapshots||[],\u8FDD\u89C4:x.violation||null};var buttons='<button class="btn primary" data-conv-action="reply" data-id="'+esc(x.messageId)+'">\u56DE\u590D</button><button class="btn" data-conv-action="set_essence" data-id="'+esc(x.messageId)+'">\u8BBE\u4E3A\u7CBE\u534E</button><button class="btn" data-conv-action="delete_essence" data-id="'+esc(x.messageId)+'">\u53D6\u6D88\u7CBE\u534E</button><button class="btn" data-conv-action="at_all" data-id="'+esc(x.messageId)+'">@\u5168\u4F53\u6210\u5458</button><button class="btn" data-conv-action="at_owner" data-id="'+esc(x.messageId)+'">@\u7FA4\u4E3B</button><button class="btn" data-conv-action="pick_admins" data-id="'+esc(x.messageId)+'">\u9009\u62E9 @\u7BA1\u7406\u5458</button><button class="btn" data-conv-action="pick_members" data-id="'+esc(x.messageId)+'">\u9009\u62E9 @\u7FA4\u6210\u5458</button><button class="btn" data-conv-action="todo" data-id="'+esc(x.messageId)+'">\u8BBE\u4E3A\u7FA4\u5F85\u529E</button><button class="btn" data-conv-action="complete_todo" data-id="'+esc(x.messageId)+'">\u5B8C\u6210\u7FA4\u5F85\u529E</button><button class="btn" data-conv-action="cancel_todo" data-id="'+esc(x.messageId)+'">\u53D6\u6D88\u7FA4\u5F85\u529E</button><button class="btn" data-conv-action="announcement" data-id="'+esc(x.messageId)+'">\u8BBE\u4E3A\u516C\u544A</button><button class="btn" data-conv-action="refresh_forward" data-id="'+esc(x.messageId)+'" '+(!(x.forwardIds||[]).length?'disabled':'')+'>\u68C0\u67E5\u8F6C\u53D1</button><button class="btn danger" data-conv-action="recall" data-id="'+esc(x.messageId)+'">\u64A4\u56DE\u6D88\u606F</button>'+(x.violationActive?'<button class="btn danger" data-conv-action="cancel_violation" data-id="'+esc(x.messageId)+'">\u53D6\u6D88\u8FDD\u89C4</button>':(conversationCapabilities.recordViolation?'<button class="btn danger" data-conv-action="mark_violation" data-id="'+esc(x.messageId)+'">\u8BB0\u5F55\u8FDD\u89C4</button>':'<button class="btn" disabled title="\u673A\u5668\u4EBA\u4E0D\u662F\u672C\u7FA4\u7BA1\u7406\uFF0C\u7FA4\u89C4\u8BB0\u5F55\u5DF2\u5B8C\u5168\u505C\u7528">\u7FA4\u89C4\u8BB0\u5F55\u5DF2\u505C\u7528</button>'));return '<div class="item conversation-card">'+badge+'<div class="item-head"><div><div class="item-title">'+esc(x.senderName||x.userId)+'\uFF08'+esc(x.userId)+'\uFF09</div><div class="item-meta">'+esc(new Date(Number(x.createdAt||0)).toLocaleString())+'\uFF5C\u6D88\u606F ID '+esc(x.messageId)+(status.length?'\uFF5C'+esc(status.join('\u3001')):'')+'</div></div></div><div class="item-body conversation-text">'+esc(x.text||'[\u65E0\u6587\u5B57\u5185\u5BB9]')+(summary.length?'<br><span class="muted">'+esc(summary.join('\uFF5C'))+'</span>':'')+conversationAttachmentHtml(x)+'</div><details class="conversation-detail"><summary>\u67E5\u770B\u9644\u4EF6\u3001\u8F6C\u53D1\u4E0E\u8FDD\u89C4\u8BE6\u7EC6\u8D44\u6599</summary><pre>'+esc(JSON.stringify(detail,null,2))+'</pre></details><div class="conversation-actions">'+buttons+'</div></div>'}
async function handleConversationAction(messageId,action){if(action==='pick_admins'){return openMemberPicker(messageId,['admin'],'\u9009\u62E9\u8981 @ \u7684\u7BA1\u7406\u5458')}if(action==='pick_members'){return openMemberPicker(messageId,['member'],'\u9009\u62E9\u8981 @ \u7684\u7FA4\u6210\u5458')}var payload={messageId:messageId,action:action};if(['reply','at_all','at_owner','at_admins','at_members','announcement'].includes(action)){var label=action==='reply'?'\u56DE\u590D\u5185\u5BB9':action==='announcement'?'\u516C\u544A\u5185\u5BB9':'\u63D0\u9192\u5185\u5BB9';var text=await textModal('\u8BF7\u8F93\u5165'+label+'\u3002','',label,{required:action==='reply'||action==='at_all',requiredMessage:'\u8BF7\u8F93\u5165\u5185\u5BB9'});if(text===null)return;payload.text=text}if(action==='mark_violation'){var reason=await textModal('\u8BF4\u660E\u8FDD\u89C4\u539F\u56E0\uFF1B\u63D0\u4EA4\u540E\u4F1A\u89E6\u53D1\u5F53\u524D\u7FA4\u7684\u8FDD\u89C4\u4EE3\u7406\u6D41\u7A0B\u3002','', '\u8BB0\u5F55\u8FDD\u89C4',{required:true,requiredMessage:'\u8BF7\u8F93\u5165\u8FDD\u89C4\u539F\u56E0'});if(reason===null)return;payload.reason=reason;payload.violationType='\u7BA1\u7406\u5458\u8BB0\u5F55';payload.severity='moderate'}if(action==='cancel_violation'){var note=await textModal('\u53D6\u6D88\u540E\u53F3\u4E0A\u89D2\u201C\u8FDD\u89C4\u4FE1\u606F\u201D\u4F1A\u6D88\u5931\uFF0C\u5E76\u5C1D\u8BD5\u64A4\u9500\u53EF\u64A4\u9500\u7684\u5904\u7F5A\u3002','\u7BA1\u7406\u5458\u590D\u6838\u540E\u53D6\u6D88\u8FDD\u89C4','\u53D6\u6D88\u8FDD\u89C4');if(note===null)return;payload.note=note}if(['recall','set_essence','delete_essence','todo','complete_todo','cancel_todo','cancel_violation'].includes(action)){if(!(await confirmModal('\u786E\u5B9A\u6267\u884C\u6B64\u64CD\u4F5C\u5417\uFF1F','\u786E\u8BA4\u64CD\u4F5C',{danger:action==='recall'||action==='cancel_violation'})))return}var r=await api('/conversations/action','POST',payload);toast(r.message||'\u64CD\u4F5C\u5B8C\u6210');if(r.ok)loadConversations()}
var memberPickerEntries=[];var memberPickerSelection=new Set();
function ensureMemberPicker(){if($('memberPicker'))return;var d=document.createElement('div');d.id='memberPicker';d.className='qqai-modal hidden';d.innerHTML='<div class="qqai-modal-card"><h3 id="memberPickerTitle">\u9009\u62E9\u7FA4\u6210\u5458</h3><input id="memberPickerSearch" class="member-picker-search" placeholder="\u641C\u7D22\u7FA4\u540D\u7247\u3001\u6635\u79F0\u3001QQ \u6216\u8EAB\u4EFD"><label class="switch"><input id="memberPickerAll" type="checkbox">\u4E00\u952E\u5168\u9009\u5F53\u524D\u641C\u7D22\u7ED3\u679C</label><div id="memberPickerList" class="member-picker-list"></div><div class="qqai-modal-actions" style="margin-top:14px"><button id="memberPickerCancel" class="btn">\u53D6\u6D88</button><button id="memberPickerOk" class="btn primary">\u7EE7\u7EED</button></div></div>';document.body.appendChild(d)}
function renderMemberPickerList(){var q=String($('memberPickerSearch').value||'').trim().toLowerCase(),visible=memberPickerEntries.filter(function(m){return !q||[m.name,m.qq,portalRoleLabel(m.role)].join(' ').toLowerCase().includes(q)});$('memberPickerList').innerHTML=visible.map(function(m){return '<label class="member-picker-row"><input type="checkbox" value="'+esc(m.qq)+'" '+(memberPickerSelection.has(String(m.qq))?'checked':'')+'><span>'+esc(m.name||m.qq)+'</span><small>'+esc(portalRoleLabel(m.role))+'\uFF5CQQ:'+esc(m.qq)+'</small></label>'}).join('')||'<div class="empty">\u6CA1\u6709\u7B26\u5408\u641C\u7D22\u6761\u4EF6\u7684\u6210\u5458</div>';$('memberPickerList').querySelectorAll('input[type=checkbox]').forEach(function(c){c.onchange=function(){if(this.checked)memberPickerSelection.add(String(this.value));else memberPickerSelection.delete(String(this.value));syncMemberPickerAll()}});syncMemberPickerAll()}
function syncMemberPickerAll(){var boxes=Array.from($('memberPickerList').querySelectorAll('input[type=checkbox]'));$('memberPickerAll').checked=boxes.length>0&&boxes.every(function(c){return c.checked});$('memberPickerAll').indeterminate=boxes.some(function(c){return c.checked})&&!$('memberPickerAll').checked}
async function openMemberPicker(messageId,roles,title){ensureMemberPicker();var r=await api('/group-members');if(!r.ok){toast(r.message);return}var roleSet=new Set(roles||[]);memberPickerEntries=(r.members||[]).filter(function(m){return roleSet.has(String(m.role||'member'))&&!m.isRobot}).map(function(m){return{qq:String(m.qq||m.user_id||''),name:String(m.name||m.card||m.nickname||m.qq||''),role:String(m.role||'member')}}).filter(function(m){return m.qq});memberPickerSelection=new Set();$('memberPickerTitle').textContent=title||'\u9009\u62E9\u7FA4\u6210\u5458';$('memberPickerSearch').value='';$('memberPicker').classList.remove('hidden');renderMemberPickerList();$('memberPickerSearch').oninput=renderMemberPickerList;$('memberPickerAll').onchange=function(){var checked=this.checked;$('memberPickerList').querySelectorAll('input[type=checkbox]').forEach(function(c){c.checked=checked;if(checked)memberPickerSelection.add(String(c.value));else memberPickerSelection.delete(String(c.value))});syncMemberPickerAll()};$('memberPickerCancel').onclick=function(){$('memberPicker').classList.add('hidden')};$('memberPickerOk').onclick=async function(){var qqs=Array.from(memberPickerSelection);if(!qqs.length){toast('\u8BF7\u81F3\u5C11\u9009\u62E9\u4E00\u540D\u6210\u5458');return}var text=await textModal('\u8BF7\u8F93\u5165\u63D0\u9192\u5185\u5BB9\u3002','\u8BF7\u67E5\u770B\u8FD9\u6761\u7FA4\u6D88\u606F\u3002','\u63D0\u9192\u5185\u5BB9');if(text===null)return;var x=await api('/conversations/action','POST',{messageId:messageId,action:'mention_selected',qqs:qqs,text:text});$('memberPicker').classList.add('hidden');toast(x.message||'\u64CD\u4F5C\u5B8C\u6210');if(x.ok)loadConversations()}}

async function loadSystemAdminDevelopers(){if(!session||!session.systemAdmin)return;var r=await raw('/api/system-admin/developers','GET');if(!r.ok){$('systemAdminStatus').textContent=r.message||'\u8BFB\u53D6\u5931\u8D25';return}$('systemAdminDeveloperIds').value=(r.managedIds||[]).join('\\n');$('systemAdminEnvironmentIds').textContent=(r.environmentIds||[]).join('\u3001')||'\u65E0';$('systemAdminStatus').textContent='\u5DF2\u52A0\u8F7D '+Number((r.managedIds||[]).length)+' \u4E2A Portal \u7BA1\u7406\u7684\u5F00\u53D1\u8005 QQ\u3002'}
async function saveSystemAdminDevelopers(){if(!session||!session.systemAdmin)return;var ids=String($('systemAdminDeveloperIds').value||'').split(/[\\n,;]+/).map(function(v){return v.trim()}).filter(Boolean),button=$('systemAdminSave');button.disabled=true;$('systemAdminStatus').textContent='\u4FDD\u5B58\u4E2D\u2026';var r=await raw('/api/system-admin/developers','POST',{ids:ids});button.disabled=false;$('systemAdminStatus').textContent=r.message||(r.ok?'\u5DF2\u4FDD\u5B58\u3002':'\u4FDD\u5B58\u5931\u8D25\u3002');if(r.ok){$('systemAdminDeveloperIds').value=(r.managedIds||[]).join('\\n');toast('\u5F00\u53D1\u8005\u540D\u5355\u5DF2\u4FDD\u5B58')}}
function showLogin(){$('login').classList.remove('hidden');$('app').classList.add('hidden')}
function showApp(){$('login').classList.add('hidden');$('app').classList.remove('hidden');closeMobileSidebar();syncResponsivePortal()}
async function loadPlatformFeatures() {
  var q = $('pfSearch') ? $('pfSearch').value : '';
  var r = await api('/platform/features?q=' + encodeURIComponent(q));
  if (!r.ok) { $('pfList').innerHTML = '<div class="empty">' + esc(r.message) + '</div>'; return; }
  $('pfSummary').textContent = '\u76EE\u5F55\u5171 ' + r.total + ' \u9879\uFF1B\u8FD9\u4E9B\u8BB0\u5F55\u76EE\u524D\u4E0D\u4F1A\u63A7\u5236\u5B9E\u9645\u6267\u884C\u3002';
  $('pfList').innerHTML = '';
  (r.features || []).forEach(function (f) {
    var d = document.createElement('div');
    d.className = 'item';
    d.innerHTML = '<div class="item-head"><div><div class="item-title">' + esc(f.id) + '\uFF5C' + esc(f.name) + '</div><div class="item-meta">\u7C7B\u522B\uFF1A' + esc(f.category) + '\uFF5C\u5B9E\u73B0\u65B9\u5F0F\uFF1A' + esc(f.mode) + '\uFF5C\u6700\u4F4E\u6743\u9650\uFF1A' + esc(portalRoleLabel(f.minRole)) + '</div></div></div>';
    var state = document.createElement('div');
    state.className = 'item-meta';
    state.textContent = '\u6267\u884C\u63A7\u5236\uFF1A\u672A\u63A5\u5165' + (f.configuredEnabled ? '\uFF1B\u5386\u53F2\u8BB0\u5F55\u4E3A\u5F00\u542F' : '\uFF1B\u5386\u53F2\u8BB0\u5F55\u4E3A\u5173\u95ED');
    d.appendChild(state);
    $('pfList').appendChild(d);
  });
  if (!$('pfList').children.length) $('pfList').innerHTML = '<div class="empty">\u6CA1\u6709\u7B26\u5408\u5F53\u524D\u6743\u9650\u6216\u641C\u7D22\u6761\u4EF6\u7684\u529F\u80FD</div>';
}
function showView(name){var view=$('v-'+name),navButton=document.querySelector('#nav button[data-view="'+name+'"]');if(!view||!navButton||navButton.hidden||navButton.style.display==='none'){toast('\u4F60\u7684\u8D26\u53F7\u6CA1\u6709\u8FD9\u4E2A\u529F\u80FD\u7684\u6743\u9650\u3002');return}document.querySelectorAll('.view').forEach(function(v){v.classList.remove('active')});document.querySelectorAll('#nav button[data-view]').forEach(function(b){b.classList.toggle('active',b.dataset.view===name)});expandSidebarGroupForView(name);refreshSidebarGroupVisibility();view.classList.add('active');$('pageTitle').textContent=titles[name]||name;try{history.replaceState(null,'','#'+name)}catch(e){}closeMobileSidebar();if(name==='overview')refreshOverview();if(name==='maintenance'){loadOperations();['opsRules','opsAppeal'].forEach(opsLoadWorkspace)}if(name==='health'){loadHealth('quick');loadModelCheckCandidates();loadOperations()}if(name==='tasks'){loadTasks();loadOperations();opsLoadTasks()}if(name==='collaboration'){loadOperations();opsLoadWorkspace('opsCollab')}if(name==='schedules'){loadSchedules();loadOperations()}if(name==='moderation')loadProposals();if(name==='models')loadModels();if(name==='quota')loadQuota();if(name==='groups')loadGroupSettings();if(name==='memory'){loadMemory();loadOperations();opsLoadWorkspace('opsKnowledge')}if(name==='logs')loadLogs();if(name==='aidecisions')loadAiDecisions();else if(name==='appeals')loadAppeals();else if(name==='appealreview')loadAppealReviews();if(name==='ruleviolations')loadRuleViolations();if(name==='violationhistory')loadViolationHistory();if(name==='settingscenter'){loadSettingsCenter();loadOperations()}if(name==='bilibili')loadBilibili();if(name==='platform')loadPlatformFeatures();if(name==='conversations')loadConversations();if(name==='systemadmin')loadSystemAdminDevelopers()}
async function loadGroupBindings(){if(!$('familyGroupChoices'))return;var r=await api('/group-bindings');if(!r.ok){$('familyBindingMessage').textContent=r.message||'\u52A0\u8F7D\u5931\u8D25';return}var groups=r.groups||[],family=r.family||null,head=(family&&family.headGroupId)||currentGroup||'';$('familyHeadGroup').innerHTML=groups.map(function(g){return '<option value="'+esc(g.groupId)+'">'+esc(g.displayName||g.groupName||g.groupId)+'\uFF08'+esc(g.groupId)+'\uFF09</option>'}).join('');$('familyHeadGroup').value=head;$('familyDefaultGroup').innerHTML=groups.map(function(g){return '<option value="'+esc(g.groupId)+'">'+esc(g.displayName||g.groupName||g.groupId)+'\uFF08'+esc(g.groupId)+'\uFF09</option>'}).join('');$('familyDefaultGroup').value=r.defaultGroupId||currentGroup||head;$('familyHeadAlias').value=family?String(family.headAlias||''):((groups.find(function(g){return g.groupId===head})||{}).displayName||'');$('familyJoinUrl').value=family?String(family.customJoinUrl||''):'';$('familyGuideText').value=family?String(family.guideText||''):'\u8BF7\u52A0\u5165\u603B\u7FA4\uFF0C\u4EE5\u4FBF\u63A5\u6536\u5B8C\u6574\u516C\u544A\u3001\u7FA4\u89C4\u4E0E\u6D3B\u52A8\u901A\u77E5\u3002';var branchMap=new Map((family&&family.branches||[]).map(function(x){return[String(x.groupId),x]}));$('familyGroupChoices').innerHTML=groups.filter(function(g){return g.groupId!==head}).map(function(g){var b=branchMap.get(String(g.groupId));return '<div class="group-binding-row"><label><input type="checkbox" data-family-group="'+esc(g.groupId)+'" '+(b?'checked':'')+'> '+esc(g.groupName||g.groupId)+'\uFF08'+esc(g.groupId)+'\uFF09</label><input data-family-alias="'+esc(g.groupId)+'" value="'+esc(b?b.alias:(g.displayName||g.groupName||g.groupId))+'" placeholder="\u663E\u793A\u540D\u79F0"><input data-family-note="'+esc(g.groupId)+'" value="'+esc(b?b.note:'')+'" placeholder="\u7528\u9014\u5907\u6CE8\uFF0C\u4F8B\u5982\uFF1A\u6E38\u620F\u5206\u7FA4\uFF0F\u901A\u77E5\u7FA4"></div>'}).join('')||'<div class="empty">\u6CA1\u6709\u5176\u4ED6\u53EF\u7ED1\u5B9A\u7FA4\u7EC4</div>';$('familyGuideBranch').innerHTML=(family&&family.branches||[]).map(function(b){return '<option value="'+esc(b.groupId)+'">'+esc(b.alias||b.groupId)+'\uFF08'+esc(b.groupId)+'\uFF09'+(b.note?'\uFF5C'+esc(b.note):'')+'</option>'}).join('')||'<option value="">\u6682\u65E0\u5206\u7FA4</option>';$('saveGroupBinding').disabled=!r.canEdit;$('familyGuideMissing').disabled=!r.canEdit||!(family&&family.branches&&family.branches.length);var direct=(family&&family.customJoinUrl)||r.generatedJoinUrl||'';$('familyJoinPreview').innerHTML=direct?'\u5B9E\u9645\u53D1\u9001\u94FE\u63A5\uFF1A<a href="'+esc(direct)+'" target="_blank" rel="noreferrer">'+esc(direct)+'</a>'+(family&&family.customJoinUrl&&r.generatedJoinUrl?'<br>\u7CFB\u7EDF\u5907\u7528\u5F15\u5BFC\u9875\uFF1A<a href="'+esc(r.generatedJoinUrl)+'" target="_blank" rel="noreferrer">'+esc(r.generatedJoinUrl)+'</a>':''):'\u4FDD\u5B58\u540E\u4F1A\u751F\u6210\u603B\u7FA4\u5F15\u5BFC\u94FE\u63A5\u3002';var roleText=family?(String(family.headGroupId)===String(currentGroup)?'\u5F53\u524D\u7FA4\u662F\u603B\u7FA4':'\u5F53\u524D\u7FA4\u662F\u5206\u7FA4\uFF0C\u6240\u5C5E\u603B\u7FA4\uFF1A'+String(family.headAlias||family.headGroupId)):'\u5F53\u524D\u7FA4\u5C1A\u672A\u52A0\u5165\u591A\u7FA4\u7ED1\u5B9A\u3002';$('familyBindingMessage').textContent=roleText+' '+(r.canEdit?'\u4F60\u53EF\u4EE5\u7F16\u8F91\u7ED1\u5B9A\u5E76\u63D0\u9192\u672A\u52A0\u5165\u603B\u7FA4\u7684\u6210\u5458\u3002':'\u53EA\u6709\u603B\u7FA4 QQ \u7BA1\u7406\u5458\u3001\u7FA4\u4E3B\u6216\u5F00\u53D1\u8005\u53EF\u4EE5\u4FEE\u6539\u7ED1\u5B9A\u3002');$('familyHeadGroup').onchange=function(){loadGroupBindingsForHeadSelection(groups,this.value)}}
function loadGroupBindingsForHeadSelection(groups,head){$('familyGroupChoices').innerHTML=groups.filter(function(g){return g.groupId!==head}).map(function(g){return '<div class="group-binding-row"><label><input type="checkbox" data-family-group="'+esc(g.groupId)+'"> '+esc(g.groupName||g.groupId)+'\uFF08'+esc(g.groupId)+'\uFF09</label><input data-family-alias="'+esc(g.groupId)+'" value="'+esc(g.displayName||g.groupName||g.groupId)+'" placeholder="\u663E\u793A\u540D\u79F0"><input data-family-note="'+esc(g.groupId)+'" value="" placeholder="\u7528\u9014\u5907\u6CE8"></div>'}).join('')||'<div class="empty">\u6CA1\u6709\u5176\u4ED6\u53EF\u7ED1\u5B9A\u7FA4\u7EC4</div>';var selected=groups.find(function(g){return g.groupId===head});$('familyHeadAlias').value=selected?(selected.displayName||selected.groupName||head):head}
async function saveGroupBindings(){var head=$('familyHeadGroup').value;if(!head){toast('\u8BF7\u9009\u62E9\u603B\u7FA4');return}var branches=[];$('familyGroupChoices').querySelectorAll('[data-family-group]:checked').forEach(function(c){var id=c.dataset.familyGroup,a=$('familyGroupChoices').querySelector('[data-family-alias="'+id+'"]'),n=$('familyGroupChoices').querySelector('[data-family-note="'+id+'"]');branches.push({groupId:id,alias:a?a.value:id,note:n?n.value:''})});var r=await api('/group-bindings','POST',{headGroupId:head,headAlias:$('familyHeadAlias').value,customJoinUrl:$('familyJoinUrl').value,guideText:$('familyGuideText').value,branches:branches});toast(r.message||'\u5B8C\u6210');if(r.ok){await loadGroups();await loadGroupBindings()}}
async function saveFamilyDefaultGroup(){var groupId=$('familyDefaultGroup').value;if(!groupId){toast('\u8BF7\u9009\u62E9\u9ED8\u8BA4\u7FA4');return}var r=await api('/group-bindings/default','POST',{groupId:groupId});toast(r.message||'\u4FDD\u5B58\u5931\u8D25')}
async function guideMissingHeadMembers(){var branch=$('familyGuideBranch').value;if(!branch){toast('\u8BF7\u9009\u62E9\u5206\u7FA4');return}if(!(await confirmModal('\u7CFB\u7EDF\u4F1A @ \u8BE5\u5206\u7FA4\u4E2D\u6240\u6709\u5C1A\u672A\u52A0\u5165\u603B\u7FA4\u7684\u6210\u5458\uFF1B\u4EBA\u6570\u4E0D\u8BBE\u5E94\u7528\u5185\u4E0A\u9650\uFF0C\u5E76\u4F1A\u81EA\u52A8\u5206\u6279\u53D1\u9001\u3002','\u63D0\u9192\u672A\u52A0\u5165\u603B\u7FA4\u6210\u5458')))return;var r=await api('/group-bindings/guide','POST',{branchGroupId:branch,text:$('familyGuideText').value,joinUrl:$('familyJoinUrl').value});toast(r.message||'\u5B8C\u6210')}


function scheduleStatusText(v){return({active:'\u6267\u884C\u4E2D',pending_owner:'\u5F85\u5F00\u53D1\u8005\u5904\u7406',pending_review:'\u5BA1\u6838\u4E2D',cancelled:'\u5DF2\u53D6\u6D88',completed:'\u5DF2\u5B8C\u6210',paused:'\u5DF2\u6682\u505C',rejected:'\u5DF2\u62D2\u7EDD',deleted:'\u5DF2\u5220\u9664'})[String(v||'')]||String(v||'\u672A\u77E5')}
function scheduleTypeText(x){if(!x)return'\u672A\u77E5';if(x.type==='once')return'\u5355\u6B21';if(x.type==='daily')return'\u6BCF\u5929 '+(x.timeOfDay||'');if(x.type==='weekly')return'\u6BCF\u5468'+('\u4E00\u4E8C\u4E09\u56DB\u4E94\u516D\u65E5'[Math.max(0,Number(x.weekday||1)-1)]||'')+' '+(x.timeOfDay||'');if(x.type==='monthly')return'\u6BCF\u6708 '+(x.dayOfMonth||'')+' \u65E5 '+(x.timeOfDay||'');if(x.type==='interval')return'\u6BCF\u9694 '+Math.max(1,Math.round(Number(x.intervalMs||0)/60000))+' \u5206\u949F';return String(x.type||'\u672A\u77E5')}
function scheduleTimeText(ms){return ms?new Date(Number(ms)).toLocaleString('zh-CN',{timeZone:'Asia/Taipei'}):'\u65E0\u4E0B\u6B21\u6267\u884C\u65F6\u95F4'}
function renderScheduleItem(x,mode){var action='';var terminal=['cancelled','completed','rejected','paused'].includes(String(x.status||''));if(mode==='mine'){action='<button class="btn" data-schedule-edit="'+esc(x.id)+'">\u7F16\u8F91\u5E76\u66F4\u65B0</button>';if(x.type!=='once'&&x.enabled&&x.status==='active')action+='<button class="btn" data-schedule-skip="'+esc(x.id)+'">\u6682\u505C\u4E00\u6B21</button>';if(x.enabled||['pending_owner','pending_review'].includes(x.status))action+='<button class="btn danger" data-schedule-cancel="'+esc(x.id)+'">\u53D6\u6D88\u6392\u7A0B</button>';if(terminal)action+='<button class="btn danger" data-schedule-delete="'+esc(x.id)+'">\u6C38\u4E45\u5220\u9664</button>'}if(mode==='review'&&['pending_review','pending_owner'].includes(x.status))action='<button class="btn primary" data-schedule-vote="approve" data-id="'+esc(x.id)+'">\u901A\u8FC7</button><button class="btn danger" data-schedule-vote="reject" data-id="'+esc(x.id)+'">\u62D2\u7EDD</button>';if(mode==='root'){action='<button class="btn" data-schedule-root="edit" data-id="'+esc(x.id)+'">\u7F16\u8F91\u5E76\u66F4\u65B0</button><button class="btn" data-schedule-root="rereview" data-id="'+esc(x.id)+'">\u91CD\u65B0 AI \u5BA1\u67E5</button>';if(x.type!=='once'&&x.enabled&&x.status==='active')action+='<button class="btn" data-schedule-root="skip_once" data-id="'+esc(x.id)+'">\u6682\u505C\u4E00\u6B21</button>';if(['pending_owner','pending_review'].includes(x.status))action+='<button class="btn primary" data-schedule-root="approve" data-id="'+esc(x.id)+'">\u5F00\u53D1\u8005\u901A\u8FC7</button><button class="btn danger" data-schedule-root="reject" data-id="'+esc(x.id)+'">\u5F00\u53D1\u8005\u62D2\u7EDD</button><button class="btn" data-schedule-root="assign" data-id="'+esc(x.id)+'">\u6307\u5B9A\u5BA1\u6838\u4EBA</button>';action+='<button class="btn danger" data-schedule-root="delete" data-id="'+esc(x.id)+'">\u6C38\u4E45\u5220\u9664</button>'}var meta='\u7F16\u53F7\uFF1A'+esc(x.id)+'\uFF5C'+esc(scheduleStatusText(x.status))+'\uFF5C'+esc(scheduleTypeText(x))+'\uFF5C\u4E0B\u6B21\uFF1A'+esc(scheduleTimeText(x.nextRunAt));if(x.creatorName||x.creatorId)meta+='\uFF5C\u5EFA\u7ACB\u8005\uFF1A'+esc(x.creatorName||x.creatorId)+'\uFF08'+esc(x.creatorId||'')+'\uFF09';var extra='';if(x.skipNextRun)extra+='<br><b>\u4E0B\u4E00\u6B21\u6267\u884C\u5C06\u8DF3\u8FC7\uFF0C\u4E4B\u540E\u81EA\u52A8\u6062\u590D\u3002</b>';if(x.lastSkippedAt)extra+='<br>\u4E0A\u6B21\u8DF3\u8FC7\uFF1A'+esc(new Date(x.lastSkippedAt).toLocaleString());if(x.lastRunAt)extra+='<br>\u4E0A\u6B21\u6267\u884C\uFF1A'+esc(new Date(x.lastRunAt).toLocaleString())+'\uFF5C\u7ED3\u679C\uFF1A'+esc(x.lastResult||'\u6210\u529F');if(x.review&&x.review.reason){var provider=x.review.provider?String(x.review.provider).replace(/^./,function(v){return v.toUpperCase()}):'AI';extra+='<br>'+esc(provider)+' \u5BA1\u67E5\uFF1A'+esc(x.review.decision||'')+'\uFF5C'+esc(x.review.reason)+(x.review.model?'\uFF5C\u6A21\u578B\uFF1A'+esc(x.review.model):'')}if(x.reviewedAgainAt)extra+='<br>\u5F00\u53D1\u8005\u91CD\u65B0\u5BA1\u67E5\uFF1A'+esc(new Date(Number(x.reviewedAgainAt)).toLocaleString());return '<div class="item"><div class="item-head"><div><div class="item-title">'+esc(x.content||'\u65E0\u5185\u5BB9')+'</div><div class="item-meta">'+meta+'</div></div><span class="status">'+esc(scheduleStatusText(x.status))+'</span></div><div class="item-body">\u65F6\u533A\uFF1A'+esc(x.timezone||'Asia/Taipei')+extra+'</div>'+(action?'<div class="row" style="margin-top:10px">'+action+'</div>':'')+'</div>'}
async function createScheduleFromPortal(){if(!currentGroup){toast('\u8BF7\u5148\u9009\u62E9\u7FA4\u7EC4');return}var text=String($('scheduleText').value||'').trim();if(!text){toast('\u8BF7\u8F93\u5165\u6392\u7A0B\u5185\u5BB9');return}var r=await api('/schedules','POST',{schedule:text});toast(r.message||'\u5B8C\u6210');if(r.ok){$('scheduleText').value='';loadSchedules()}}
async function cancelScheduleFromPortal(id){if(!(await confirmModal('\u53D6\u6D88\u540E\u4E0D\u4F1A\u518D\u6267\u884C\uFF0C\u5DF2\u53D1\u9001\u7684\u6D88\u606F\u4E0D\u4F1A\u88AB\u64A4\u56DE\u3002','\u53D6\u6D88\u6392\u7A0B',{danger:true})))return;var r=await api('/schedules','DELETE',{id:id});toast(r.message||'\u5B8C\u6210');if(r.ok)loadSchedules()}
async function editScheduleFromPortal(id){var r=await api('/schedules');if(!r.ok)return toast(r.message||'\u8BFB\u53D6\u5931\u8D25');var x=(r.schedules||[]).find(function(v){return String(v.id)===String(id)});if(!x)return toast('\u627E\u4E0D\u5230\u8BE5\u6392\u7A0B');var spec=await textModal('\u7F16\u8F91\u6392\u7A0B\u65F6\u95F4\u4E0E\u5185\u5BB9',x.scheduleSpec||x.content||'','\u7F16\u8F91\u6392\u7A0B',{placeholder:'\u4F8B\u5982\uFF1A\u6BCF\u5929 18:00 @123456789 \u63D0\u9192\u5185\u5BB9'});if(spec===null)return;if(!String(spec).trim())return toast('\u6392\u7A0B\u5185\u5BB9\u4E0D\u80FD\u4E3A\u7A7A');var y=await api('/schedules/edit','POST',{id:id,schedule:String(spec).trim()});toast(y.message||'\u66F4\u65B0\u5931\u8D25');if(y.ok)loadSchedules()}
async function deleteScheduleFromPortal(id){if(!(await confirmModal('\u6C38\u4E45\u5220\u9664\u540E\u65E0\u6CD5\u6062\u590D\uFF0C\u786E\u5B9A\u7EE7\u7EED\u5417\uFF1F','\u6C38\u4E45\u5220\u9664\u6392\u7A0B',{danger:true})))return;var r=await api('/schedules/delete','POST',{id:id});toast(r.message||'\u5220\u9664\u5931\u8D25');if(r.ok)loadSchedules()}
async function skipScheduleOnceFromPortal(id){if(!(await confirmModal('\u53EA\u8DF3\u8FC7\u4E0B\u4E00\u6B21\u6267\u884C\uFF0C\u4E4B\u540E\u4F1A\u81EA\u52A8\u6062\u590D\u3002','\u6682\u505C\u4E00\u6B21')))return;var r=await api('/schedules/skip-once','POST',{id:id});toast(r.message||'\u64CD\u4F5C\u5931\u8D25');if(r.ok)loadSchedules()}
async function voteScheduleFromPortal(id,vote){var r=await api('/review/schedule','POST',{id:id,vote:vote});toast(r.message||'\u5BA1\u6838\u5B8C\u6210');if(r.ok)loadSchedules()}
async function rootScheduleAction(id,action){if(action==='assign'){var reviewers=await textModal('\u8F93\u5165\u5177\u6709\u6392\u7A0B\u5BA1\u6838\u6743\u9650\u7684 QQ\uFF0C\u53EF\u7528\u9017\u53F7\u6216\u7A7A\u683C\u5206\u9694\u3002','', '\u6307\u5B9A\u6392\u7A0B\u5BA1\u6838\u4EBA',{required:true,requiredMessage:'\u8BF7\u8F93\u5165\u5BA1\u6838\u4EBA QQ'});if(reviewers===null)return;var rule=await textModal('\u5BA1\u6838\u89C4\u5219\u53EF\u8F93\u5165 single\u3001majority \u6216 all\u3002','single','\u5BA1\u6838\u89C4\u5219',{required:true});if(rule===null)return;var a=await api('/root/schedule-assign','POST',{id:id,reviewerIds:String(reviewers).split(/[,\\s]+/).filter(Boolean),approvalRule:String(rule).trim()});toast(a.message||'\u5DF2\u6307\u6D3E');if(a.ok)loadSchedules();return}if(action==='edit'){var all=await api('/root/schedules');var x=(all.schedules||[]).find(function(v){return String(v.id)===String(id)});var spec=await textModal('\u5F00\u53D1\u8005\u53EF\u76F4\u63A5\u4FEE\u6539\u65F6\u95F4\u4E0E\u5185\u5BB9\uFF1B\u5DF2\u5B8C\u6210\u7684\u5355\u6B21\u6392\u7A0B\u4F1A\u636E\u65B0\u65F6\u95F4\u91CD\u65B0\u542F\u7528\u3002',x&&(x.scheduleSpec||x.content)||'','\u7F16\u8F91\u5E76\u66F4\u65B0\u6392\u7A0B',{required:true});if(spec===null)return;var e=await api('/root/schedule-action','POST',{id:id,action:'edit',schedule:String(spec).trim()});toast(e.message||'\u66F4\u65B0\u5931\u8D25');if(e.ok)loadSchedules();return}if(action==='delete'&&!(await confirmModal('\u6C38\u4E45\u5220\u9664\u6B64\u6392\u7A0B\u4E0E\u5176\u8BB0\u5F55\uFF1F','\u5F00\u53D1\u8005\u6C38\u4E45\u5220\u9664',{danger:true})))return;if(action==='skip_once'&&!(await confirmModal('\u53EA\u6682\u505C\u4E0B\u4E00\u6B21\u6267\u884C\uFF0C\u4E4B\u540E\u81EA\u52A8\u6062\u590D\u3002','\u6682\u505C\u4E00\u6B21')))return;var r=await api('/root/schedule-action','POST',{id:id,action:action});toast(r.message||'\u5904\u7406\u5B8C\u6210');if(r.ok)loadSchedules()}
async function loadSchedules(){if(!$('scheduleMine'))return;if(!currentGroup){$('scheduleMine').innerHTML='<div class="empty">\u8BF7\u5148\u9009\u62E9\u7FA4\u7EC4\u3002</div>';return}var r=await api('/schedules');if(!r.ok){$('scheduleMine').innerHTML='<div class="empty">'+esc(r.message)+'</div>';return}var cron=r.cron||{};$('scheduleCronState').textContent=cron.lastRunAt?'Cron \u6700\u8FD1\u6267\u884C\uFF1A'+new Date(Number(cron.lastRunAt)).toLocaleString()+(cron.recent?'\uFF08\u6B63\u5E38\uFF09':'\uFF08\u8D85\u8FC7 5 \u5206\u949F\uFF0C\u53EF\u80FD\u672A\u6301\u7EED\u89E6\u53D1\uFF09'):(cron.message||'\u5C1A\u672A\u8BB0\u5F55 Cron \u6267\u884C');$('scheduleMine').innerHTML=(r.schedules||[]).map(function(x){return renderScheduleItem(x,'mine')}).join('')||'<div class="empty">\u76EE\u524D\u7FA4\u6CA1\u6709\u4F60\u5EFA\u7ACB\u7684\u6392\u7A0B</div>';$('scheduleMine').querySelectorAll('[data-schedule-cancel]').forEach(function(b){b.onclick=function(){cancelScheduleFromPortal(this.dataset.scheduleCancel)}});$('scheduleMine').querySelectorAll('[data-schedule-delete]').forEach(function(b){b.onclick=function(){deleteScheduleFromPortal(this.dataset.scheduleDelete)}});$('scheduleMine').querySelectorAll('[data-schedule-edit]').forEach(function(b){b.onclick=function(){editScheduleFromPortal(this.dataset.scheduleEdit)}});$('scheduleMine').querySelectorAll('[data-schedule-skip]').forEach(function(b){b.onclick=function(){skipScheduleOnceFromPortal(this.dataset.scheduleSkip)}});var canReview=!!(r.permissions&&r.permissions.canReview),dev=!!(r.permissions&&r.permissions.developer);$('scheduleReviewCard').classList.toggle('hidden',!canReview);$('scheduleRootCard').classList.toggle('hidden',!dev);if(canReview){var q=await api('/review/schedules');$('scheduleReviewList').innerHTML=q.ok?(q.schedules||[]).map(function(x){return renderScheduleItem(x,'review')}).join('')||'<div class="empty">\u6CA1\u6709\u5206\u914D\u7ED9\u4F60\u7684\u6392\u7A0B\u5BA1\u6838</div>':'<div class="empty">'+esc(q.message||'\u65E0\u6CD5\u8BFB\u53D6\u5BA1\u6838\u6392\u7A0B')+'</div>';$('scheduleReviewList').querySelectorAll('[data-schedule-vote]').forEach(function(b){b.onclick=function(){voteScheduleFromPortal(this.dataset.id,this.dataset.scheduleVote)}})}if(dev){var all=await api('/root/schedules');$('scheduleRootList').innerHTML=all.ok?(all.schedules||[]).map(function(x){return renderScheduleItem(x,'root')}).join('')||'<div class="empty">\u6CA1\u6709\u6392\u7A0B</div>':'<div class="empty">'+esc(all.message||'\u65E0\u6CD5\u8BFB\u53D6\u5168\u90E8\u6392\u7A0B')+'</div>';$('scheduleRootList').querySelectorAll('[data-schedule-root]').forEach(function(b){b.onclick=function(){rootScheduleAction(this.dataset.id,this.dataset.scheduleRoot)}})}}

async function loadGroups(){var r=await api('/groups');if(!r.ok){toast(r.message);return false}var sel=$('groupSelect'),groups=r.groups||[];sel.innerHTML='<option value="">\u9009\u62E9\u7FA4\u7EC4</option>';groups.forEach(function(g){var o=document.createElement('option');o.value=g.groupId;o.textContent=(g.displayName||g.groupName||g.groupId)+' ('+g.groupId+')';sel.appendChild(o)});if(r.selectedGroupId){sel.value=r.selectedGroupId;currentGroup=r.selectedGroupId}else if(groups.length===1){sel.value=groups[0].groupId;await selectGroup(groups[0].groupId)}else if(!groups.length){toast('\u6CA1\u6709\u627E\u5230\u4F60\u5DF2\u52A0\u5165\u4E14\u542F\u7528 QQAI \u7684\u7FA4\u7EC4\uFF1B\u4ECD\u53EF\u4F7F\u7528\u533F\u540D\u7533\u8BC9\u4E0E\u4E2A\u4EBA\u529F\u80FD\u3002')}return true}
async function selectGroup(id){if(!id){currentGroup='';setNativeAdminVisibility(false);refreshOverview();return}var r=await api('/select-group','POST',{groupId:id});if(!r.ok){toast(r.message);return}currentGroup=id;session=r.session;renderPortalIdentity(window.__qqaiPortalAccount||{},session);await refreshCapabilities();applyR3RoleVisibility();toast('\u5DF2\u5207\u6362\u7FA4\u7EC4');refreshOverview()}
function ensureAccountSecurityPanel(){var view=$('v-settingscenter');if(!view||$('accountSecurityPanel'))return;var panel=document.createElement('div');panel.id='accountSecurityPanel';panel.className='card';panel.style.marginBottom='16px';panel.innerHTML='<div class="section-head" style="margin-bottom:12px"><div><h3>\u767B\u5F55\u4E0E\u53CC\u56E0\u6570\u9A8C\u8BC1</h3><p>\u9A8C\u8BC1\u7801\u767B\u5F55\u6C38\u8FDC\u4FDD\u7559\uFF1B\u5BC6\u7801\u4E3A\u53EF\u9009\u3002\u542F\u7528 2FA \u540E\uFF0C\u5BC6\u7801\u767B\u5F55\u8FD8\u9700\u8981\u9A8C\u8BC1\u5668\u52A8\u6001\u7801\u3001\u5355\u6B21\u5907\u7528\u7801\u6216 QQ \u79C1\u4FE1\u9A8C\u8BC1\u7801\u3002</p></div><button id="authSecurityReload" class="btn">\u5237\u65B0\u72B6\u6001</button></div><div id="authSecurityStatus" class="notice">\u5C1A\u672A\u52A0\u8F7D\u3002</div><div class="security-grid" style="margin-top:14px"><div class="card"><h3>\u8BBE\u7F6E\u6216\u4FEE\u6539\u5BC6\u7801</h3><div class="field"><label>\u5F53\u524D\u5BC6\u7801\uFF08\u9996\u6B21\u8BBE\u7F6E\u53EF\u7559\u7A7A\uFF09</label><input id="authCurrentPassword" type="password" autocomplete="current-password"></div><div class="field"><label>\u65B0\u5BC6\u7801\uFF08\u81F3\u5C11 10 \u4E2A\u5B57\u7B26\uFF09</label><input id="authNewPassword" type="password" maxlength="128" autocomplete="new-password"></div><div class="field"><label>\u786E\u8BA4\u65B0\u5BC6\u7801</label><input id="authConfirmPassword" type="password" maxlength="128" autocomplete="new-password"></div><div class="field"><label>QQ \u9A8C\u8BC1\u7801\uFF08\u767B\u5F55\u8D85\u8FC7 15 \u5206\u949F\u6216\u5FD8\u8BB0\u5F53\u524D\u5BC6\u7801\u65F6\u4F7F\u7528\uFF09</label><input id="authVerificationCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></div><div class="row"><button id="authSendCode" class="btn ghost">\u53D1\u9001 QQ \u9A8C\u8BC1\u7801</button><button id="authSavePassword" class="btn primary">\u4FDD\u5B58\u5BC6\u7801</button></div></div><div class="card"><h3>\u53CC\u56E0\u6570\u9A8C\u8BC1\uFF08TOTP\uFF09</h3><div class="field"><label>\u5F53\u524D\u5BC6\u7801</label><input id="auth2faPassword" type="password" autocomplete="current-password"></div><div class="row"><button id="auth2faSetup" class="btn primary">\u5F00\u59CB\u8BBE\u7F6E 2FA</button><button id="auth2faDisable" class="btn danger">\u5173\u95ED 2FA</button></div><div id="auth2faSetupArea" class="hidden"><div class="field"><label>\u9A8C\u8BC1\u5668\u5BC6\u94A5</label><input id="auth2faSecret" readonly></div><div class="field"><label>otpauth URI</label><textarea id="auth2faUri" readonly></textarea></div><div class="field"><label>\u9A8C\u8BC1\u5668\u5F53\u524D\u516D\u4F4D\u52A8\u6001\u7801</label><input id="auth2faCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></div><div class="row"><button id="auth2faEnable" class="btn primary">\u9A8C\u8BC1\u5E76\u542F\u7528</button><button id="authBackupRegenerate" class="btn">\u91CD\u65B0\u751F\u6210\u5907\u7528\u7801</button></div></div></div></div><div id="authBackupCodes" class="notice hidden backup-codes"></div>';var anchor=$('scMessage');view.insertBefore(panel,anchor||view.firstChild);$('authSecurityReload').onclick=loadAccountSecurity;$('authSendCode').onclick=sendAccountSecurityCode;$('authSavePassword').onclick=saveAccountPassword;$('auth2faSetup').onclick=setupAccount2fa;$('auth2faEnable').onclick=enableAccount2fa;$('auth2faDisable').onclick=disableAccount2fa;$('authBackupRegenerate').onclick=regenerateBackupCodes}
async function loadAccountSecurity(){if(!$('authSecurityStatus'))return;var r=await api('/security/auth-state');if(!r.ok){$('authSecurityStatus').textContent=r.message||'\u8BFB\u53D6\u5931\u8D25';return}$('authSecurityStatus').textContent='\u5BC6\u7801\uFF1A'+(r.passwordSet?'\u5DF2\u8BBE\u7F6E':'\u672A\u8BBE\u7F6E')+'\uFF1B\u53CC\u56E0\u6570\u9A8C\u8BC1\uFF1A'+(r.twoFactorEnabled?'\u5DF2\u542F\u7528':'\u672A\u542F\u7528')+(r.twoFactorEnabled?'\uFF1B\u5269\u4F59\u5907\u7528\u7801 '+Number(r.backupCodesRemaining||0)+' \u7EC4':'')+(r.encryptionReady?'':'\uFF1B\u7BA1\u7406\u5458\u5C1A\u672A\u8BBE\u7F6E PORTAL_AUTH_SECRET\uFF0C\u6682\u65F6\u4E0D\u80FD\u542F\u7528 2FA');$('auth2faSetup').disabled=!r.passwordSet||!r.encryptionReady||r.twoFactorEnabled;$('auth2faDisable').disabled=!r.twoFactorEnabled;$('authBackupRegenerate').disabled=!r.twoFactorEnabled;$('auth2faSetupArea').classList.toggle('hidden',!r.twoFactorEnabled)}
async function sendAccountSecurityCode(){if(!session)return;var r=await raw('/api/auth/request-code','POST',{qq:session.qq});toast(r.message||'\u53D1\u9001\u5931\u8D25')}
async function saveAccountPassword(){var next=$('authNewPassword').value,confirm=$('authConfirmPassword').value;if(next!==confirm){toast('\u4E24\u6B21\u8F93\u5165\u7684\u65B0\u5BC6\u7801\u4E0D\u4E00\u81F4');return}var r=await api('/security/password','POST',{currentPassword:$('authCurrentPassword').value,newPassword:next,verificationCode:$('authVerificationCode').value});toast(r.message||'\u4FDD\u5B58\u5931\u8D25');if(r.ok){$('authCurrentPassword').value='';$('authNewPassword').value='';$('authConfirmPassword').value='';$('authVerificationCode').value='';loadAccountSecurity()}}
async function setupAccount2fa(){var r=await api('/security/2fa/setup','POST',{currentPassword:$('auth2faPassword').value});toast(r.message||'\u8BBE\u7F6E\u5931\u8D25');if(!r.ok)return;$('auth2faSetupArea').classList.remove('hidden');$('auth2faSecret').value=r.secret||'';$('auth2faUri').value=r.uri||'';$('auth2faCode').focus()}
function showBackupCodes(codes,message){var box=$('authBackupCodes');box.classList.remove('hidden');box.textContent=String(message||'\u8BF7\u4FDD\u5B58\u5907\u7528\u7801')+'\\n\\n'+(codes||[]).join('\\n')+'\\n\\n\u6BCF\u7EC4\u5907\u7528\u7801\u53EA\u80FD\u4F7F\u7528\u4E00\u6B21\u3002\u5173\u95ED\u6216\u5237\u65B0\u9875\u9762\u540E\u4E0D\u4F1A\u518D\u6B21\u663E\u793A\u539F\u6587\u3002'}
async function enableAccount2fa(){var r=await api('/security/2fa/enable','POST',{code:$('auth2faCode').value});toast(r.message||'\u542F\u7528\u5931\u8D25');if(r.ok){showBackupCodes(r.backupCodes,r.message);$('auth2faPassword').value='';$('auth2faCode').value='';loadAccountSecurity()}}
async function regenerateBackupCodes(){var code=$('auth2faCode').value;if(!code){toast('\u8BF7\u5148\u8F93\u5165\u9A8C\u8BC1\u5668\u5F53\u524D\u516D\u4F4D\u52A8\u6001\u7801');return}if(!(await confirmModal('\u65E7\u5907\u7528\u7801\u4F1A\u7ACB\u5373\u5168\u90E8\u5931\u6548\uFF0C\u786E\u5B9A\u91CD\u65B0\u751F\u6210\u5417\uFF1F','\u91CD\u65B0\u751F\u6210\u5907\u7528\u7801')))return;var r=await api('/security/2fa/backup-codes','POST',{code:code});toast(r.message||'\u751F\u6210\u5931\u8D25');if(r.ok)showBackupCodes(r.backupCodes,r.message)}
async function disableAccount2fa(){var password=$('auth2faPassword').value,code=$('auth2faCode').value;if(!password||!code){toast('\u5173\u95ED 2FA \u9700\u8981\u5F53\u524D\u5BC6\u7801\u548C\u9A8C\u8BC1\u5668\u52A8\u6001\u7801');return}if(!(await confirmModal('\u5173\u95ED\u540E\u6240\u6709\u5907\u7528\u7801\u90FD\u4F1A\u5931\u6548\uFF0C\u786E\u5B9A\u7EE7\u7EED\u5417\uFF1F','\u5173\u95ED\u53CC\u56E0\u6570\u9A8C\u8BC1')))return;var r=await api('/security/2fa/disable','POST',{currentPassword:password,code:code});toast(r.message||'\u5173\u95ED\u5931\u8D25');if(r.ok){$('auth2faPassword').value='';$('auth2faCode').value='';$('auth2faSetupArea').classList.add('hidden');$('authBackupCodes').classList.add('hidden');loadAccountSecurity()}}
function renderPortalIdentity(account,currentSession){account=account||{};currentSession=currentSession||{};var title=account.displayName||(currentSession.systemAdmin?(currentSession.username||'\u7CFB\u7EDF\u7BA1\u7406\u5458'):(currentSession.qq?'QQ '+currentSession.qq:'QQ \u4F7F\u7528\u8005'));var meta=currentSession.systemAdmin?'\u7CFB\u7EDF\u7BA1\u7406\u5458':((account.qq||currentSession.qq)?'QQ '+(account.qq||currentSession.qq)+'\uFF5C':'')+portalRoleLabel(currentSession.role||account.groupRole||'member');$('identity').innerHTML='<b>'+esc(title)+'</b><br><span style="color:#98a2b7">'+esc(meta)+'</span>'}
async function boot(attempt){attempt=Number(attempt||0);migratePortalMaintenanceV140();ensureR3Views();ensureAccountSecurityPanel();organizeSidebarNavigation();bindDashboardActions();var me=await api('/me');if(!me.ok){if(me.retryable||me.code==='SESSION_STORAGE_UNAVAILABLE'){setNativeAdminVisibility(false);$('loginNotice').textContent=me.message||'\u767B\u5F55\u4F1A\u8BDD\u8D44\u6599\u5E93\u6682\u65F6\u4E0D\u53EF\u7528\uFF0C\u6B63\u5728\u91CD\u8BD5\u2026';if(attempt<3){setTimeout(function(){boot(attempt+1)},500*(attempt+1));return}showLogin();return}setNativeAdminVisibility(false);showLogin();return}showApp();session=me.session;window.__qqaiPortalAccount=me.account||{};if($('accountSecurityPanel'))$('accountSecurityPanel').classList.toggle('hidden',!!session.systemAdmin);if(!session.systemAdmin)loadAccountSecurity();renderPortalIdentity(window.__qqaiPortalAccount,session);var loaded=await loadGroups();if(!loaded)return;await refreshCapabilities();applyR3RoleVisibility();var hash=String(location.hash||'').replace(/^#/,'');if(hash&&$('v-'+hash)){var b=document.querySelector('#nav button[data-view="'+hash+'"]');if(b&&!b.hidden&&b.style.display!=='none')showView(hash);else showView('overview')}else showView('overview')}
async function loadHealth(mode){$('healthList').innerHTML='<div class="empty">\u68C0\u67E5\u4E2D\u2026</div>';var r=await api('/health?mode='+encodeURIComponent(mode||'quick'));if(!r.checks){$('healthList').innerHTML='<div class="empty">'+esc(r.message||'\u68C0\u67E5\u5931\u8D25')+'</div>';return}renderHealth(r)}
function renderHealth(r){$('healthSummary').innerHTML='<div class="card span-4"><div class="metric-label">\u6B63\u5E38</div><div class="metric-value">'+esc(r.counts.ok)+'</div></div><div class="card span-4"><div class="metric-label">\u8B66\u544A</div><div class="metric-value">'+esc(r.counts.warning)+'</div></div><div class="card span-4"><div class="metric-label">\u9519\u8BEF</div><div class="metric-value">'+esc(r.counts.error)+'</div></div>';$('healthList').innerHTML=(r.checks||[]).map(function(c){var detail=c.error||humanizeHealthDetail(c.detail);return '<div class="health-card"><div class="item-head"><div class="item-title">'+esc(c.name)+'</div><span class="status '+statusClass(c.status)+'">'+esc(healthStatusText(c.status))+'</span></div><div class="latency">\u8017\u65F6\uFF1A'+esc(c.latencyMs)+' ms</div><div class="detail">'+esc(detail)+'</div></div>'}).join('')||'<div class="empty">\u6CA1\u6709\u68C0\u67E5\u9879\u76EE</div>';var issues=(r.checks||[]).filter(function(c){return c.status!=='ok'});$('overviewIssues').innerHTML=issues.map(function(c){return '<div class="item"><div class="item-head"><div class="item-title">'+esc(c.name)+'</div><span class="status '+statusClass(c.status)+'">'+esc(healthStatusText(c.status))+'</span></div><div class="item-meta">'+esc(c.error||humanizeHealthDetail(c.detail))+'</div></div>'}).join('')||'<div class="empty">\u6240\u6709\u68C0\u67E5\u9879\u76EE\u6B63\u5E38</div>';$('overallStatus').className='status '+(r.ok?'ok':'error');$('overallStatus').textContent=r.ok?'\u7CFB\u7EDF\u6B63\u5E38':'\u9700\u8981\u5904\u7406'}
