  var actions=a.status==='trusted'?'<button class="btn danger" data-author-revoke="'+esc(a.keyId)+'">\u64A4\u9500 Key</button>':'<span class="status warning">REVOKED</span>';
  actions+='<button class="btn" data-author-delete="'+esc(a.keyId)+'">\u5220\u9664\u8BB0\u5F55</button>';
